<template>
  <academy-layout ref="layout" :title="mode === 'mock' ? '模拟考试' : '题库练习'">
    <view v-if="screen === 'setup'">
      <view class="academy-section"><view class="academy-section__head"><view><text class="academy-section__title">选择练习方式</text><text class="academy-section__note">练习逐题返回解析，模拟考统一交卷后返回结果</text></view></view><view class="mode-grid"><view class="academy-tile mode-tile" :class="{ selected: mode === 'practice' }" @tap="mode = 'practice'"><text class="academy-tile__title">章节练习</text><text class="academy-tile__note">提交单题后查看答案与来源</text></view><view class="academy-tile mode-tile" :class="{ selected: mode === 'mock' }" @tap="mode = 'mock'"><text class="academy-tile__title">模拟考试</text><text class="academy-tile__note">计时、暂存、统一交卷</text></view></view></view>
      <view class="academy-section"><view class="academy-section__head"><text class="academy-section__title">题型</text></view><view class="academy-chip-row"><text class="academy-chip" :class="{ 'academy-chip--active': type === 'all' }" @tap="type = 'all'">综合</text><text v-for="item in catalog" :key="item.type" class="academy-chip" :class="{ 'academy-chip--active': type === item.type }" @tap="type = item.type">{{ item.label }} {{ item.count }}</text><text class="academy-chip" :class="{ 'academy-chip--active': type === 'wrong' }" @tap="type = 'wrong'">错题</text></view></view>
      <view v-if="error" class="academy-state"><text class="academy-state__title">无法开始练习</text><text class="academy-state__note">{{ error }}</text></view>
      <view class="academy-panel setup-note"><text>题目由考试会话接口下发。正式题库答案不随题目列表返回，只在提交后由服务端判题。</text><view class="academy-button" :class="{ 'academy-button--disabled': starting }" @tap="startExam">{{ starting ? '准备题目' : '开始' }}</view></view>
    </view>

    <view v-else-if="screen === 'exam' && currentQuestion" class="exam-shell">
      <view class="exam-toolbar"><view><text class="exam-count">{{ currentIndex + 1 }} / {{ session.questions.length }}</text><text class="academy-tag">{{ typeLabel(currentQuestion.type) }}</text></view><view class="exam-timer" :class="{ urgent: remainingSeconds <= 60 && mode === 'mock' }">{{ mode === 'mock' ? formattedTime : '练习模式' }}</view></view>
      <view class="academy-progress"><view class="academy-progress__value" :style="{ width: ((currentIndex + 1) / session.questions.length * 100) + '%' }" /></view>
      <view class="question-panel"><text class="question-stem">{{ currentQuestion.stem }}</text><text v-if="currentQuestion.type === 'multiple'" class="academy-section__note">多选题，请选择全部正确选项</text><view class="option-list"><view v-for="(option, index) in currentQuestion.options" :key="option.id" class="option-row" :class="optionClass(option.id)" @tap="toggleOption(option.id)"><text class="option-letter">{{ optionLetter(index) }}</text><text>{{ option.text }}</text></view></view>
        <view v-if="feedback" class="feedback" :class="feedback.correct ? 'correct' : 'wrong'"><text class="feedback__title">{{ feedback.correct ? '回答正确' : '回答错误' }}</text><text class="feedback__answer">正确答案：{{ feedback.answer.map(answerLabel).join('、') }}</text><text class="feedback__explanation">{{ feedback.explanation }}</text><text class="academy-source">解析来源：{{ feedback.source }}</text></view>
      </view>
      <view class="exam-navigation"><view class="academy-button academy-button--secondary academy-button--small" :class="{ 'academy-button--disabled': currentIndex === 0 }" @tap="move(-1)">上一题</view><view class="academy-button academy-button--secondary academy-button--small" @tap="saveDraft(true)">暂存</view><view v-if="mode === 'practice' && !feedback" class="academy-button academy-button--small" :class="{ 'academy-button--disabled': !currentAnswer.length }" @tap="submitCurrent">提交本题</view><view v-else-if="currentIndex < session.questions.length - 1" class="academy-button academy-button--small" @tap="move(1)">下一题</view><view v-else class="academy-button academy-button--small" @tap="requestSubmit">交卷</view></view>
      <view class="question-map"><text v-for="(question, index) in session.questions" :key="question.id" class="question-map__item" :class="{ current: index === currentIndex, answered: (answers[question.id] || []).length }" @tap="currentIndex = index">{{ index + 1 }}</text></view>
    </view>

    <view v-else-if="screen === 'result'" class="result-screen">
      <view class="result-score"><text>{{ result.score }}</text><text>分</text><text>答对 {{ result.correctCount }} / {{ result.total }} 题</text></view>
      <view class="academy-section"><view class="academy-section__head"><text class="academy-section__title">答题解析</text></view><view class="academy-list"><view v-for="(detail, index) in result.details" :key="detail.questionId" class="academy-panel result-item"><view class="result-item__head"><text>第 {{ questionNumber(detail.questionId) }} 题</text><text class="academy-tag" :class="detail.correct ? 'academy-tag--accent' : 'academy-tag--danger'">{{ detail.correct ? '正确' : '错题' }}</text></view><text class="result-item__stem">{{ questionById(detail.questionId)?.stem }}</text><text>正确答案：{{ detail.answer.map(answerLabelFor(detail.questionId)).join('、') }}</text><text class="academy-section__note">{{ detail.explanation }}</text><text class="academy-source">{{ detail.source }}</text></view></view></view>
      <view class="academy-actions result-actions"><view class="academy-button academy-button--secondary" @tap="reset">返回题库</view><view class="academy-button" @tap="retryWrong">练习错题</view></view>
    </view>
    <confirm-dialog :visible="confirmSubmit" title="确认交卷" :message="`已答 ${answeredCount}/${session?.questions?.length || 0} 题，交卷后不能修改答案。`" @cancel="confirmSubmit = false" @confirm="submitAll" />
  </academy-layout>
</template>

<script>
import AcademyLayout from './AcademyLayout.vue'
import ConfirmDialog from '../../shared/components/ConfirmDialog.vue'
import { academyService } from '../services'
import { getRouteOptions } from '../../shared/utils/route-options'
export default {
  name: 'ExamPage', components: { AcademyLayout, ConfirmDialog },
  data() { const options = getRouteOptions(); return { screen: 'setup', mode: options.mode === 'mock' ? 'mock' : 'practice', type: options.type || 'all', catalog: [], error: '', starting: false, session: null, currentIndex: 0, answers: {}, feedbackByQuestion: {}, remainingSeconds: 0, timer: null, lastDraftSavedAt: 0, confirmSubmit: false, result: null } },
  computed: { currentQuestion() { return this.session?.questions?.[this.currentIndex] }, currentAnswer() { return this.answers[this.currentQuestion?.id] || [] }, feedback() { return this.feedbackByQuestion[this.currentQuestion?.id] }, answeredCount() { return this.session ? this.session.questions.filter((question) => (this.answers[question.id] || []).length).length : 0 }, formattedTime() { const minutes = Math.floor(this.remainingSeconds / 60).toString().padStart(2, '0'); const seconds = (this.remainingSeconds % 60).toString().padStart(2, '0'); return `${minutes}:${seconds}` } },
  async mounted() { try { this.catalog = await academyService.getQuestionCatalog() } catch (error) { this.error = error.message } },
  beforeUnmount() { if (this.timer) clearInterval(this.timer); if (this.screen === 'exam') this.saveDraft(false) },
  methods: {
    async startExam() { this.starting = true; this.error = ''; try { this.session = await academyService.createExamSession({ mode: this.mode, type: this.type, count: this.mode === 'mock' ? 8 : 5 }); this.answers = {}; this.feedbackByQuestion = {}; this.currentIndex = 0; this.remainingSeconds = this.session.durationSeconds; this.screen = 'exam'; if (this.mode === 'mock') this.startTimer() } catch (error) { this.error = error.message } finally { this.starting = false } },
    startTimer() { if (this.timer) clearInterval(this.timer); this.timer = setInterval(() => { if (this.remainingSeconds <= 1) { this.remainingSeconds = 0; clearInterval(this.timer); this.timer = null; this.submitAll(true); return } this.remainingSeconds -= 1; if (this.remainingSeconds % 30 === 0) this.saveDraft(false) }, 1000) },
    toggleOption(id) { if (this.feedback) return; const question = this.currentQuestion; const current = [...this.currentAnswer]; if (question.type === 'multiple') { const index = current.indexOf(id); if (index >= 0) current.splice(index, 1); else current.push(id); this.answers[question.id] = current } else this.answers[question.id] = [id] },
    optionClass(id) { return { selected: this.currentAnswer.includes(id), correct: this.feedback?.answer.includes(id), wrong: Boolean(this.feedback && this.currentAnswer.includes(id) && !this.feedback.answer.includes(id)) } },
    async submitCurrent() { if (!this.currentAnswer.length) return; try { const feedback = await academyService.submitPracticeAnswer(this.session.id, this.currentQuestion.id, this.currentAnswer); this.feedbackByQuestion[this.currentQuestion.id] = feedback; await this.saveDraft(false) } catch (error) { this.$refs.layout.showToast(error.message) } },
    move(delta) { const next = this.currentIndex + delta; if (next < 0 || next >= this.session.questions.length) return; this.currentIndex = next },
    async saveDraft(notify) { if (!this.session) return; try { await academyService.saveExamDraft(this.session.id, { mode: this.mode, answers: this.answers, currentIndex: this.currentIndex, remainingSeconds: this.remainingSeconds }); this.lastDraftSavedAt = Date.now(); if (notify) this.$refs.layout.showToast('答题进度已暂存') } catch (error) { if (notify) this.$refs.layout.showToast(error.message) } },
    requestSubmit() { this.confirmSubmit = true },
    async submitAll(auto = false) { this.confirmSubmit = false; if (this.timer) { clearInterval(this.timer); this.timer = null } try { this.result = await academyService.submitExam(this.session.id, this.answers, this.mode); this.screen = 'result'; if (auto) this.$refs.layout.showToast('考试时间到，已自动交卷') } catch (error) { this.$refs.layout.showToast(error.message); if (this.mode === 'mock' && this.remainingSeconds > 0) this.startTimer() } },
    reset() { this.screen = 'setup'; this.session = null; this.result = null; this.answers = {}; this.feedbackByQuestion = {} }, retryWrong() { this.reset(); this.mode = 'practice'; this.type = 'wrong' },
    typeLabel(type) { return { single: '单选题', multiple: '多选题', judge: '判断题' }[type] || type }, optionLetter(index) { return ['A', 'B', 'C', 'D', 'E'][index] }, answerLabel(id) { return this.currentQuestion?.options?.find((item) => item.id === id)?.text || id }, answerLabelFor(questionId) { const question = this.questionById(questionId); return (id) => question?.options?.find((item) => item.id === id)?.text || id }, questionById(id) { return this.session.questions.find((question) => question.id === id) }, questionNumber(id) { return this.session.questions.findIndex((question) => question.id === id) + 1 }
  }
}
</script>

<style scoped>
.mode-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14rpx; }.mode-tile { min-height: 130rpx; }.mode-tile.selected { border-color: var(--accent); background: rgba(25,207,160,.08); }.setup-note { display: flex; align-items: center; justify-content: space-between; gap: 24rpx; color: var(--muted); font-size: 22rpx; }.exam-toolbar { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14rpx; }.exam-toolbar > view:first-child { display: flex; align-items: center; gap: 12rpx; }.exam-count { color: var(--text); font-size: 25rpx; font-weight: 700; }.exam-timer { color: var(--accent); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 26rpx; font-weight: 700; }.exam-timer.urgent { color: var(--academy-danger); }.question-panel { margin-top: 24rpx; }.question-stem { display: block; margin-bottom: 24rpx; color: var(--text); font-size: 32rpx; font-weight: 700; line-height: 1.55; }.option-list { display: flex; flex-direction: column; gap: 12rpx; }.option-row { display: flex; min-height: 78rpx; align-items: center; gap: 14rpx; padding: 15rpx; border: 1rpx solid var(--line); border-radius: 12rpx; background: var(--surface); color: var(--text); font-size: 24rpx; }.option-row.selected { border-color: var(--accent); background: rgba(25,207,160,.08); }.option-row.correct { border-color: var(--accent); }.option-row.wrong { border-color: var(--academy-danger); }.option-letter { flex: 0 0 auto; display: flex; width: 42rpx; height: 42rpx; align-items: center; justify-content: center; border: 1rpx solid currentColor; border-radius: 9rpx; font-size: 20rpx; }.feedback { margin-top: 22rpx; padding: 20rpx; border: 1rpx solid var(--line); border-radius: 12rpx; background: var(--surface); }.feedback.correct { border-color: var(--accent); }.feedback.wrong { border-color: var(--academy-danger); }.feedback__title { display: block; color: var(--text); font-size: 26rpx; font-weight: 700; }.feedback__answer, .feedback__explanation { display: block; margin-top: 9rpx; color: var(--muted); font-size: 22rpx; }.exam-navigation { display: flex; justify-content: flex-end; flex-wrap: wrap; gap: 10rpx; margin: 24rpx 0; }.question-map { display: grid; grid-template-columns: repeat(8, minmax(0, 1fr)); gap: 8rpx; }.question-map__item { display: flex; aspect-ratio: 1; align-items: center; justify-content: center; border: 1rpx solid var(--line); border-radius: 8rpx; color: var(--muted); font-size: 20rpx; }.question-map__item.answered { border-color: var(--accent); color: var(--accent); }.question-map__item.current { background: var(--accent); color: var(--accent-ink); }.result-score { display: flex; flex-direction: column; align-items: center; padding: 44rpx 20rpx; }.result-score text:first-child { color: var(--accent); font-size: 94rpx; font-weight: 780; line-height: 1; }.result-score text:nth-child(2) { color: var(--muted); font-size: 24rpx; }.result-score text:last-child { margin-top: 12rpx; color: var(--text); font-size: 25rpx; }.result-item { display: flex; flex-direction: column; gap: 10rpx; font-size: 22rpx; }.result-item__head { display: flex; align-items: center; justify-content: space-between; color: var(--text); font-weight: 700; }.result-item__stem { color: var(--text); font-size: 24rpx; }.result-actions { justify-content: center; }
</style>
